//! Opaque identity primitives.
//!
//! The identity of a library or of a media file is an opaque identifier
//! generated by the domain. It is never derived from the path: renaming or moving a file
//! cannot change the identity of another record, and the same location reused
//! does not reuse the identity by accident.
//!
//! The identifiers are UUID version 7, sortable by creation instant.
//!
//! Generation uses the system clock. A clock before the Unix epoch or an unavailable source of
//! randomness would make `Uuid::now_v7` panic; those scenarios require a fundamentally
//! broken system and are recorded as a known limitation, instead of being masked by a
//! repeated identifier.

use uuid::Uuid;

/// Generates an opaque library identifier.
pub fn new_library_id() -> String {
    Uuid::now_v7().to_string()
}

/// Generates an opaque media identifier.
///
/// This is the identifier exposed to the frontend: the interface points at the media by
/// `media_id`, never by the file's path.
pub fn new_media_id() -> String {
    Uuid::now_v7().to_string()
}

/// Generates an opaque study-note identifier.
pub fn new_note_id() -> String {
    Uuid::now_v7().to_string()
}

/// Generates an opaque PDF-annotation identifier.
pub fn new_annotation_id() -> String {
    Uuid::now_v7().to_string()
}

/// Generates an opaque study-card (flashcard) identifier.
pub fn new_card_id() -> String {
    Uuid::now_v7().to_string()
}

/// Generates an opaque time-marker identifier.
pub fn new_bookmark_id() -> String {
    Uuid::now_v7().to_string()
}

/// Generates an opaque identifier for a sync operation or a device.
pub fn new_sync_id() -> String {
    Uuid::now_v7().to_string()
}
